ITEMS = {'Alpha': 1, 'Beta': 2}

def lookup(name: str):
    return ITEMS.get(name)

import unittest
from src.catalog import lookup

class CatalogTests(unittest.TestCase):
    def test_exact_lookup(self):
        self.assertEqual(lookup('Alpha'), 1)

if __name__ == '__main__':
    unittest.main()

